solution:
#include <stdio.h>

int is_prime(int p) {
    if (p < 2) return 0;
    for (int d = 2; d * d <= p; d++) {
        if (p % d == 0) return 0;
    }
    return 1;
}

int main(void) {
    int n;
    scanf("%d", &n);
    int p = n + 1;
    while (!is_prime(p)) p++;
    printf("%d\n", p);
    return 0;
}
